     * Encode a character for URLs
     *
     * @param immune characters not to encode
     * @param c      character to encode
     * @return the encoded string representing c
     */
    public String encodeCharacter(char[] immune, Character c) {
        if (c == null) {
            throw new IllegalArgumentException("Character to encode cannot be null");
        }

        // Build a set of characters that should remain unencoded.
        Set<Character> unencoded = UNENCODED_SET;
        if (immune != null && immune.length > 0) {
            Set<Character> temp = new HashSet<Character>(UNENCODED_SET.size() + immune.length);
            temp.addAll(UNENCODED_SET);
            for (char ic : immune) {
                temp.add(ic);
            }
            unencoded = Collections.unmodifiableSet(temp);
        }

        String cStr = String.valueOf(c);
        if (unencoded.contains(c)) {
            return cStr;
        }

        byte[] bytes = toUtf8Bytes(cStr);
        StringBuilder sb = new StringBuilder(bytes.length * 3);
        for (byte b : bytes) {
            appendTwoUpperHex(sb.append('%'), b);
        }
        return sb.toString();
    }

    private static StringBuilder appendTwoUpperHex(StringBuilder sb, int b) {
        int unsigned = b & 0xFF;
        sb.append("0123456789ABCDEF".charAt(unsigned >>> 4));
        sb.append("0123456789ABCDEF".charAt(unsigned & 0x0F));
        return sb;
    }

    private static byte[] toUtf8Bytes(String str) {
        return str.getBytes(StandardCharsets.UTF_8);
    }

    // other methods
}
