import java.io.File;
import java.io.IOException;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new {@link File} inside {@code dir} with a sanitized {@code name}.
     * <p>
     * The method protects against directory‑traversal attacks by:
     * <ul>
     *   <li>Rejecting absolute paths.</li>
     *   <li>Removing query parameters.</li>
     *   <li>Ensuring the resolved canonical path stays within {@code dir}.</li>
     * </ul>
     *
     * @param dir  the target directory (must not be {@code null})
     * @param name the desired file name (must not be {@code null} or empty)
     * @return a {@link File} instance that does not conflict with existing files
     * @throws IllegalArgumentException if {@code dir} or {@code name} is invalid
     * @throws SecurityException        if the resolved path escapes {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Directory must not be null");
        }
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("Name must not be null or empty");
        }

        // Strip query parameters (e.g., "file.txt?foo=bar")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject absolute paths – they would ignore the supplied directory
        if (new File(name).isAbsolute()) {
            throw new SecurityException("Absolute paths are not allowed: " + name);
        }

        // Construct the initial file reference
        File file = new File(dir, name);

        // Resolve canonical paths to eliminate "..", ".", and symlinks
        String canonicalDir;
        String canonicalFile;
        try {
            canonicalDir = dir.getCanonicalPath();
            canonicalFile = file.getCanonicalPath();
        } catch (IOException e) {
            throw new RuntimeException("Failed to resolve canonical paths", e);
        }

        // Ensure the file resides within the intended directory
        if (!canonicalFile.startsWith(canonicalDir + File.separator)) {
            throw new SecurityException(
                    "Attempted directory traversal: " + canonicalFile + " is outside " + canonicalDir);
        }

        // Generate a unique filename if one already exists
        String dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
            try {
                canonicalFile = file.getCanonicalPath();
            } catch (IOException e) {
                throw new RuntimeException("Failed to resolve canonical path during uniqueness check", e);
            }
            if (!canonicalFile.startsWith(canonicalDir + File.separator)) {
                throw new SecurityException(
                        "Attempted directory traversal during uniqueness check: " + canonicalFile);
            }
        }

        // Ensure the parent directory exists
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            if (!parent.mkdirs() && !parent.isDirectory()) {
                throw new RuntimeException("Failed to create parent directories for " + file);
            }
        }

        return file;
    }

    // other methods

}
