        }

        // Count leading slashes
        int i = 0;
        while (i < path.length() && path.charAt(i) == '/') {
            i++;
        }

        // Extract the remainder after the leading slashes
        final String rest = path.substring(i);

        // Prepend a single slash to guarantee a proper path format
