public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    /* --------------------------------------------------------------------- */
    /* Whitelist of safe component types                                    */
    /* --------------------------------------------------------------------- */

    /** Set of classes considered safe for array deserialization. */
    private static final Set<Class<?>> SAFE_TYPES;

    static {
        Set<Class<?>> tmp = new HashSet<>();
        tmp.add(byte.class);
        tmp.add(Byte.class);
        tmp.add(short.class);
        tmp.add(Short.class);
        tmp.add(int.class);
        tmp.add(Integer.class);
        tmp.add(long.class);
        tmp.add(Long.class);
        tmp.add(float.class);
        tmp.add(Float.class);
        tmp.add(double.class);
        tmp.add(Double.class);
        tmp.add(boolean.class);
        tmp.add(Boolean.class);
        tmp.add(char.class);
        tmp.add(Character.class);
        tmp.add(String.class);
        tmp.add(java.math.BigDecimal.class);
        tmp.add(java.math.BigInteger.class);
        tmp.add(java.util.Date.class);
        tmp.add(java.sql.Timestamp.class);
        tmp.add(java.sql.Time.class);
        tmp.add(java.sql.Date.class);
