        // Handle JSON null
        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        // Handle string literal -> byte[]
        if (lexer.token() == JSONToken.LITERAL_STRING) {
            // Only allow this conversion when the target component type is byte[]
            Class<?> targetComponent = resolveComponentClass(type, parser);
            if (!byte[].class.equals(targetComponent)) {
                throw new IllegalArgumentException("Unexpected string literal for non-byte[] component");
            }
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        // Resolve component class
        Class<?> componentClass = resolveComponentClass(type, parser);
        if (!isSafeComponent(componentClass)) {
            throw new IllegalArgumentException(
                    "Deserialization of component type [" + componentClass.getName() + "] is not allowed");
        }

        JSONArray array = new JSONArray();
        try {
            parser.parseArray(componentClass, array, fieldName);
        } catch (RuntimeException ex) {
            throw new IllegalArgumentException("Failed to parse array: " + ex.getMessage(), ex);
        }

        return (T) toObjectArray(parser, componentClass, array);
    }

