    private Class<?> resolveComponentClass(Type type, DefaultJSONParser parser) {
        Class<?> componentClass;
        Type componentType;

        if (type instanceof GenericArrayType) {
            GenericArrayType gat = (GenericArrayType) type;
            componentType = gat.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                TypeVariable<?> tv = (TypeVariable<?>) componentType;
                Type contextType = parser.getContext().type;

                if (contextType instanceof ParameterizedType) {
                    ParameterizedType pt = (ParameterizedType) contextType;
                    Type raw = pt.getRawType();
                    if (raw instanceof Class) {
                        TypeVariable<?>[] params = ((Class<?>) raw).getTypeParameters();
                        for (int i = 0; i < params.length; i++) {
                            if (params[i].getName().equals(tv.getName())) {
                                componentType = pt.getActualTypeArguments()[i];
                                break;
                            }
                        }
                    }
                } else {
                    componentType = tv.getBounds()[0];
                }
            }

            componentClass = TypeUtils.getClass(componentType);
            if (componentClass == null) {
                componentClass = Object.class;
            }
        } else {
            Class<?> clazz = (Class<?>) type;
            componentClass = clazz.getComponentType();
            componentType = componentClass;
        }

        return componentClass;
    }

